import json
from itertools import permutations

RIDERS = ["R", "S", "T", "Y"]
BIKES = ["F", "G", "H", "J"]

def valid(d1, d2):
    # Each day: every rider tests one bike, all four bikes used once.
    # Each rider tests a different bike on day 2 than day 1.
    for r in RIDERS:
        if d1[r] == d2[r]:
            return False
    # Reynaldo cannot test F (applied to both days).
    if d1["R"] == "F" or d2["R"] == "F":
        return False
    # Yuki cannot test J (applied to both days).
    if d1["Y"] == "J" or d2["Y"] == "J":
        return False
    # Theresa must be one of the testers for H.
    if "H" not in (d1["T"], d2["T"]):
        return False
    # The bike Yuki tests on day 1 must be tested by Seamus on day 2.
    if d2["S"] != d1["Y"]:
        return False
    # Hypothetical: Theresa tests J on the first day.
    if d1["T"] != "J":
        return False
    return True

def assignments():
    for p1 in permutations(BIKES):
        d1 = dict(zip(RIDERS, p1))
        for p2 in permutations(BIKES):
            d2 = dict(zip(RIDERS, p2))
            if valid(d1, d2):
                yield d1, d2

options = {
    "A": lambda d1, d2: d2["R"] == "G",
    "B": lambda d1, d2: d1["S"] == "H",
    "C": lambda d1, d2: d2["Y"] == "H",
    "D": lambda d1, d2: "J" in (d1["S"], d2["S"]),
    "E": lambda d1, d2: "G" in (d1["T"], d2["T"]),
}

sols = list(assignments())
possible = []
evidence = {"valid_scenarios": len(sols)}
for key, cond in options.items():
    hit = any(cond(d1, d2) for d1, d2 in sols)
    evidence[key] = hit
    if hit:
        possible.append(key)

if len(possible) == 1:
    final = possible[0]
else:
    final = "UNSUPPORTED"

print(json.dumps({"final_answer": final, "evidence": evidence}, sort_keys=True))
